const root=document.querySelector('#app');
const state={config:null,me:null,workspace:null,churchId:null,tab:'overview',roles:[],team:null,statements:[],events:[],sessions:[],mfa:null,mfaSetup:null,recoveryCodes:[],mfaCsrf:null,directory:null,inbox:null,enquiry:null,inboxStatus:'new',inboxPage:1,website:null,websiteAssets:[],websiteRevisions:[],websiteMessages:[],websiteSection:'pages',websitePage:'home',websiteEntry:'',websiteDirty:false,websiteMessageStatus:'pending',websiteRevisionsMore:false,websiteMessagesMore:false};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>({overview:'◈',profile:'▤',purpose:'✧',branches:'⌘',team:'♧',roles:'▦',audit:'◷'}[name]||'→');
const pretty=s=>s.replaceAll('-',' ').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const allowed=p=>state.workspace?.permissions.includes(p);
const globalScope=()=>!state.workspace?.scope;
function notice(message,error=false){const el=document.querySelector('#notice');el.textContent=message;el.className=error?'visible error':'visible';clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.className='',6000);}
async function api(path,method='GET',body) {
  const response=await fetch(path,{method,credentials:'same-origin',headers:{...(method!=='GET'?{'Content-Type':'application/json'}:{}),...((path==='/api/auth/mfa/login'?state.mfaCsrf:state.me?.csrf)?{'X-CSRF-Token':path==='/api/auth/mfa/login'?state.mfaCsrf:state.me.csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
  const data=await response.json();if(!response.ok){const error=new Error(data.error||'Please try again.');error.status=response.status;throw error;}return data;
}
const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(name,label,value='',extra='')=>`<label>${esc(label)}<textarea name="${esc(name)}" rows="4" ${extra}>${esc(value)}</textarea></label>`;
const select=(name,label,options,value='',extra='')=>`<label>${esc(label)}<select name="${esc(name)}" ${extra}>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const brand=`<a class="brand" href="/app"><img src="/icon.svg" alt="" width="36" height="36"><span>JesusSeat<span class="brand-tag">A home for your ministry</span></span></a>`;
const credit=`<span>An evangelical product of <a href="https://www.ndovera.com" target="_blank" rel="noopener noreferrer">Ndovera Limited ↗</a></span>`;
function pageTitle(title){document.title=`${title} · JesusSeat`;}
function authFrame(title,subtitle,content){pageTitle(title);root.innerHTML=`<div class="auth-layout"><aside class="auth-story">${brand}<div class="story-copy"><div class="eyebrow light">FAITH. PEOPLE. PURPOSE.</div><h1>More time for<br>what matters.</h1><p>A thoughtful workspace to organise your church, care for your people and grow together.</p><div class="story-line"></div><blockquote>“Let all things be done decently and in order.”<cite>1 Corinthians 14:40 · KJV</cite></blockquote></div><footer>${credit}</footer></aside><main id="main" class="auth-main"><a class="mobile-brand" href="/app">JesusSeat</a><div class="auth-card"><span class="eyebrow">YOUR MINISTRY STARTS HERE</span><h2>${title}</h2><p class="muted">${subtitle}</p>${content}<p class="form-error" role="alert"></p></div><footer class="auth-bottom">Free church registration <span>•</span> Built around your community</footer></main></div>`;}
function authentication() {
  const path=location.pathname;
  if(path==='/participation') {
    authFrame('Our shared commitment','Participation requirements · draft for review',`<article class="policy"><p>JesusSeat is an evangelical product operated by Ndovera Limited. Participating churches must teach sound biblical doctrine, affirm the authority of Scripture and the Gospel of Jesus Christ, and represent their ministry honestly.</p><p>Churches must safeguard children and vulnerable people, respect others, obtain permission to publish personal information or photographs, protect confidential records, and avoid abuse, impersonation, unlawful content or fraudulent fundraising.</p><p>Church administrators are responsible for authorised access and accurate records. Reports of misuse may lead to investigation and proportionate restrictions, with a review process.</p><p>This is the initial participation draft, version ${esc(state.config.policyVersion)}. Full Terms, Statement of Faith and Privacy Policy require completion before public launch. Registration is not a public verification badge.</p><p>Account details, church records and security history are stored to operate the workspace. Invitations and recovery messages use email. Do not enter live pastoral, child or financial records into an unapproved test deployment.</p><a href="/new-church">Return to church setup →</a></article>`);return;
  }
  if(path==='/verify') {
    authFrame('Verify your email','Confirm your address to create or join a church.',`<form data-form="verify"><button class="button" type="submit">Verify my email →</button></form><p class="auth-link"><a href="/login">Back to sign in</a></p>`);return;
  }
  if(path==='/reset') {
    authFrame('Choose a new password','Use at least 12 characters, ideally a unique passphrase.',`<form data-form="reset">${field('password','New password','','password','required minlength="12" maxlength="256" autocomplete="new-password"')}<button class="button">Update password →</button></form><p class="auth-link"><a href="/login">Back to sign in</a></p>`);return;
  }
  if(path==='/forgot') {
    authFrame('Find your way back','We will email a recovery link if your account exists.',`<form data-form="forgot">${field('email','Email address','','email','required autocomplete="email"')}<button class="button">Request recovery link →</button></form><p class="auth-link"><a href="/login">Back to sign in</a></p>`);return;
  }
  if(path==='/register') {
    authFrame('Create your account','Start with your details. Your church comes next.',`<form data-form="register">${field('name','Your full name','','text','required minlength="2" maxlength="100" autocomplete="name"')}${field('email','Email address','','email','required autocomplete="email"')}${field('password','Password','','password','required minlength="12" maxlength="256" autocomplete="new-password"')}<small>Use a unique passphrase with at least 12 characters.</small><button class="button">Create free account →</button></form><p class="auth-link">Already part of JesusSeat? <a href="/login">Sign in</a></p>`);return;
  }
  authFrame('Welcome back','Sign in to care for your church community.',`<form data-form="login">${field('email','Email address','','email','required autocomplete="username"')}${field('password','Password','','password','required maxlength="256" autocomplete="current-password"')}<a class="forgot" href="/forgot">Forgot password?</a><button class="button">Sign in to JesusSeat →</button></form><p class="auth-link">New to JesusSeat? <a href="/register">Create a free account</a></p>${sessionStorage.getItem('invitation')?'<div class="soft-note">Sign in with the invited email address to join your church.</div>':''}`);
}
function empty(title,description){return `<div class="empty"><span>✧</span><h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function workspaceChooser(){pageTitle('Your churches');root.innerHTML=`<header class="simple-header">${brand}<div class="account">${platformInboxLink()}<a href="/security">Account security</a><button class="text-button" data-action="logout">Sign out</button></div></header><main id="main" class="choose"><div class="eyebrow">WELCOME, ${esc(state.me.user.name.split(' ')[0]).toUpperCase()}</div><h1>Your ministry,<br>in one place.</h1><p class="muted">Open your worker workspace or register a church.</p>${verificationBanner()}${!state.me.churches.length?'<p class="soft-note">Church workers receive dashboard access through an invitation from their church administrator.</p>':''}<div class="workspace-grid">${state.me.churches.map(c=>`<button class="workspace-card" data-church="${esc(c.id)}"><div class="workspace-icon">${esc(c.name[0])}</div><h3>${esc(c.name)}</h3><p>${esc(c.role)} · ${esc(c.status)}</p><span>Open workspace →</span></button>`).join('')}<a class="workspace-card new-card" href="/new-church"><span class="new-plus">＋</span><h3>Register a church</h3><p>Free to get started. Ready for your purpose.</p><span>Create workspace →</span></a></div>${credit}</main>`;}
function verificationBanner(){return state.me.user.verified?'':`<div class="banner"><div><strong>One more step: verify your email</strong><p>Check ${esc(state.me.user.email)} for your verification link. Your address must be verified before you create or join a church.</p></div><button class="button secondary" data-action="resend">Resend email</button></div>`;}
function newChurch(){pageTitle('Register your church');root.innerHTML=`<header class="simple-header">${brand}<a href="/app">Your workspaces ↗</a></header><main id="main" class="setup-page"><span class="eyebrow">A NEW CHAPTER</span><h1>Make room for<br>your community.</h1><p class="muted">Create your church workspace. You can complete the details together.</p>${verificationBanner()}<form data-form="church" class="panel setup-form"><div class="panel-heading"><span class="step-number">01</span><div><h3>Introduce your church</h3><p>The foundation for your ministry workspace.</p></div></div>${field('name','Church name','','text','required minlength="2" maxlength="160"')}${field('slug','Church web address','','text','required minlength="3" maxlength="60" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="your-church-name"')}<small>Your church’s reserved JesusSeat address.</small><div class="form-grid">${field('country','Country','','text','required placeholder="Nigeria" maxlength="80"')}${field('city','City / town','','text','required placeholder="Abuja" maxlength="100"')}</div>${select('structure','Church structure',[['independent','Independent church'],['multi_branch','Church with multiple branches'],['denomination','Denomination / church network']])}${field('timezone','Timezone',Intl.DateTimeFormat().resolvedOptions().timeZone,'text','required placeholder="Africa/Lagos" maxlength="80"')}<label class="check"><input name="acceptPolicy" type="checkbox" required><span>I have read and accept the <a href="/terms" target="_blank" rel="noopener">participation requirements and statement of faith draft</a>, and I am authorised to register this church.</span></label><div class="form-error" role="alert"></div><button class="button" ${!state.me.user.verified?'disabled':''}>Create church workspace →</button></form></main>`;}
async function loadWorkspace(churchId,tab='overview') {
  const w=await api(`/api/churches/${churchId}`);state.workspace=w;state.churchId=churchId;state.tab=tab;
  if(tab==='team'||tab==='roles') {const r=await api(`/api/churches/${churchId}/roles`);state.roles=r.roles;if(tab==='team')state.team=await api(`/api/churches/${churchId}/team`);}
  if(tab==='purpose')state.statements=(await api(`/api/churches/${churchId}/statements`)).statements;
  if(tab==='website'){const [site,assets,revisions,messages]=await Promise.all([api(`/api/churches/${churchId}/website`),api(`/api/churches/${churchId}/website/assets`),api(`/api/churches/${churchId}/website/revisions`),api(`/api/churches/${churchId}/website/messages?status=${state.websiteMessageStatus}`)]);state.website=site;state.websiteAssets=assets.assets;state.websiteRevisions=revisions.revisions;state.websiteMessages=messages.messages;state.websiteMessagesMore=messages.messages.length===25;state.websiteRevisionsMore=revisions.revisions.length===30;state.websiteDirty=false;if(!site.snapshot.pages.some(p=>p.slug===state.websitePage))state.websitePage='home';}
  if(tab==='directory')state.directory=(await api(`/api/churches/${churchId}/directory`)).listing;
  if(tab==='audit')state.events=(await api(`/api/churches/${churchId}/audit`)).events;
  history.replaceState(null,'',`/app?church=${encodeURIComponent(churchId)}&tab=${encodeURIComponent(tab)}`);renderWorkspace();
}
function renderWorkspace() {
  const w=state.workspace,c=w.church;
  const navigation=[['overview','Overview',true],['profile','Church profile',allowed('church.manage')&&globalScope()],['purpose','Vision & mission',true],['branches','Church structure',true],['team','Your team',allowed('team.read')],['roles','Roles & permissions',allowed('team.read')],['website','Church website',allowed('website.manage')&&globalScope()],['directory','Public listing',allowed('church.manage')&&globalScope()],['audit','Activity history',allowed('audit.read')&&globalScope()]].filter(x=>x[2]);
  if(!navigation.some(n=>n[0]===state.tab))state.tab='overview';
  pageTitle(`${navigation.find(n=>n[0]===state.tab)?.[1]} · ${c.name}`);
  root.innerHTML=`<div class="workspace-shell"><aside class="sidebar">${brand}<div class="workspace-label">CHURCH WORKSPACE</div><a class="church-switch" href="/app"><div class="workspace-icon small">${esc(c.name[0])}</div><div><strong>${esc(c.name)}</strong><small>Switch workspace ↗</small></div></a><nav aria-label="Workspace">${navigation.map(([key,title])=>`<button class="nav-item ${state.tab===key?'active':''}" data-tab="${key}" ${state.tab===key?'aria-current="page"':''}><span>${icon(key)}</span>${title}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-card"><span>BUILT FOR YOUR PURPOSE</span><p>A little organisation.<br>More room for ministry.</p></div><a href="https://www.ndovera.com" target="_blank" rel="noopener noreferrer">By Ndovera Limited ↗</a></div></aside><div class="workspace-body"><header class="topbar"><span class="breadcrumb">Your workspace <span>/</span> ${esc(navigation.find(n=>n[0]===state.tab)?.[1])}</span><div class="account"><span class="avatar">${esc(state.me.user.name[0])}</span><span>${esc(state.me.user.name)}</span>${platformInboxLink()}<a href="/security">Security</a><button data-action="logout" class="text-button">Sign out</button></div></header><main id="main" class="dashboard">${content()}</main><footer class="dashboard-footer">${credit}<span>JesusSeat · Grow together</span></footer></div></div>`;
}
function heading(kicker,title,description){return `<div class="page-heading"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>`;}
function content(){
  const w=state.workspace,c=w.church,base=`/api/churches/${state.churchId}`;
  if(state.tab==='overview') {
    const done=w.onboarding.filter(t=>t.done).length,total=w.onboarding.length;
    return `${heading('YOUR CHURCH, CONNECTED',`Welcome home, ${esc(state.me.user.name.split(' ')[0])}.`,'Build a strong foundation. Make more space for your people.')}<section class="welcome-banner"><div><span class="eyebrow light">${esc(c.name)}</span><h2>Great ministry starts<br>with a little preparation.</h2><p>${globalScope()?'Let’s get your church workspace ready, one thoughtful step at a time.':'You are viewing your assigned ministry workspace.'}</p>${allowed('church.manage')&&globalScope()?'<button class="button gold" data-tab="profile">Complete church profile →</button>':''}</div><div class="banner-art" aria-hidden="true"><span>✧</span><div class="arch arch-one"></div><div class="arch arch-two"></div><div class="art-caption">FAITH · PEOPLE · PURPOSE</div></div></section><div class="stats"><div class="stat"><span>Workspace setup</span><strong>${total?`${done} <small>/ ${total}</small>`:'Scoped'}</strong><p>${total?'Steps completed':'Your assigned access'}</p></div><div class="stat"><span>${w.scope?'Visible locations':'Church locations'}</span><strong>${w.branches.length}</strong><p>${esc(pretty(c.structure))}</p></div><div class="stat"><span>Website direction</span><strong class="stat-text">${esc(pretty(c.template))}</strong><p>Selected template preference</p></div></div><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">YOUR NEXT STEPS</span><h3>Prepare your workspace</h3></div><span class="pill">${done} complete</span></div>${total?w.onboarding.map((t,i)=>`<button class="checklist-item" data-tab="${t.href}" ${((t.href==='profile'||t.href==='purpose')&&!allowed('church.manage'))|| (t.href==='team'&&!allowed('team.read'))?'disabled':''}><span class="task-circle ${t.done?'done':''}">${t.done?'✓':i+1}</span><span>${esc(t.label)}<small>${t.done?'Completed':'Ready when you are'}</small></span><span class="arrow">↗</span></button>`).join(''):empty('Your ministry workspace','Your church administrator manages church-wide onboarding.')}</section><aside class="panel purpose-aside"><span class="eyebrow">A SHARED FOUNDATION</span><span class="purpose-symbol">✧</span><h3>One community.<br>A shared purpose.</h3><p>Give your team a clear picture of the vision and mission that guide your church.</p><button class="button secondary" data-tab="purpose">Explore your purpose →</button><hr><small>Registered in ${esc(c.city)}, ${esc(c.country)}<br>Timezone: ${esc(c.timezone)}</small></aside></div>`;
  }
  if(state.tab==='profile')return `${heading('THE FOUNDATION','Tell your church’s story.','Keep your contact details, service information and welcome message together.')}<form data-form="profile" class="panel wide-form">${field('name','Church name',c.name,'text','required minlength="2" maxlength="160"')}<div class="form-grid">${field('contact_email','Church contact email',c.contact_email,'email','required')}${field('phone','Phone number',c.phone,'tel','maxlength="50"')}</div>${area('welcome','Welcome message',c.welcome,'maxlength="2000" placeholder="A warm introduction to your church community…"')}${area('service_times','Service times',c.service_times,'maxlength="1000" placeholder="Sunday worship — 9:00 AM\nWednesday Bible study — 6:00 PM"')}${select('template','Website template preference',state.config.templates.map(t=>[t,pretty(t)]),c.template)}<small>Set your website design and publish your pages in Church website.</small><div class="form-error" role="alert"></div><button class="button">Save church profile →</button></form>`;
  if(state.tab==='purpose')return `${heading('WHAT GUIDES YOUR MINISTRY','Vision & mission.','Create multiple statements to express your church’s purpose.')}<div class="dashboard-columns"><section>${state.statements.length?state.statements.map(s=>`<article class="panel statement"><span class="eyebrow">${esc(s.kind)}</span><h3>${esc(s.title)}</h3><p class="preserve">${esc(s.body)}</p>${allowed('church.manage')&&globalScope()?`<details><summary>Edit statement</summary><form data-form="statement-edit" data-id="${s.id}">${field('title','Title',s.title,'text','required maxlength="160"')}${area('body','Statement',s.body,'required maxlength="5000"')}${field('position','Display order',s.position,'number','required min="0" max="10000"')}<button class="button secondary">Save changes</button></form></details><button class="text-button danger" data-delete-statement="${s.id}">Delete statement</button>`:''}</article>`).join(''):empty('Your purpose belongs here','Add the vision and mission that guide your community.')}</section>${allowed('church.manage')&&globalScope()?`<form data-form="statement" class="panel"><h3>Add a statement</h3>${select('kind','Statement type',[['vision','Vision'],['mission','Mission']])}${field('title','Title','','text','required minlength="2" maxlength="160"')}${area('body','Statement','','required minlength="5" maxlength="5000"')}<div class="form-error" role="alert"></div><button class="button">Add statement →</button></form>`:''}</div>`;
  if(state.tab==='branches')return `${heading('CONNECTED IN PURPOSE','Your church structure.','Organise locations and leadership levels around the way your church serves.')}<div class="dashboard-columns"><section class="panel"><h3>${esc(pretty(c.structure))}</h3><div class="branch-list">${w.branches.map(b=>`<article class="branch"><span class="branch-dot"></span><div><span class="eyebrow">${esc(b.label)}</span><h4>${esc(b.name)}</h4><p>${esc(b.location||'Location not set')}${b.parent_id?` · Within ${esc(w.branches.find(p=>p.id===b.parent_id)?.name||'assigned hierarchy')}`:''}</p></div></article>`).join('')}</div></section>${allowed('branches.manage')&&c.structure!=='independent'?`<form data-form="branch" class="panel"><h3>Add a location or level</h3>${field('name','Name','','text','required minlength="2" maxlength="160"')}${field('label','Level label','','text','required minlength="2" maxlength="50" placeholder="Branch, district, region…"')}${field('location','Location','','text','maxlength="200"')}${select('parent_id','Reports to',[...(globalScope()?[['','Church-wide / no parent']]:[]),...w.branches.map(b=>[b.id,b.name])])}<div class="form-error" role="alert"></div><button class="button">Add to structure →</button></form>`:'<div class="soft-note">Your administrator manages the church structure. Independent churches use a single church location.</div>'}</div>`;
  if(state.tab==='team') {
    const options=state.roles.filter(r=>r.permissions.every(p=>w.permissions.includes(p))&&(!['church_admin','pastor','head_usher'].includes(r.builtin)||(w.workerRole==='church_admin'&&!w.scope))).map(r=>[r.id,r.name]);
    return `${heading('SERVING TOGETHER','Your ministry team.','Invite people, assign responsibilities and give each person the access they need.')}<div class="panel table-panel"><h3>People with workspace access</h3><div class="table-scroll"><table><thead><tr><th>Person</th><th>Role</th><th>Scope</th><th>Manage</th></tr></thead><tbody>${state.team.members.map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small></td><td>${esc(m.role)}${m.worker_suspended_at?'<small>Dashboard suspended</small>':''}</td><td>${esc(m.branch_id?w.branches.find(b=>b.id===m.branch_id)?.name||'Assigned branch':'Whole church')}</td><td>${allowed('team.manage')&&m.user_id!==state.me.user.id?m.worker_suspended_at?'<span class="muted">Department assignment required</span>':`<details><summary>Edit access</summary><form data-form="member" data-id="${m.id}">${select('role_id','Role',options,m.role_id)}${branchSelect(m.branch_id||'')}<button class="button secondary">Save</button></form>${m.builtin!=='member'?`<button class="text-button danger" data-remove-member="${m.id}">Suspend worker access</button>`:''}</details>`:'—'}</td></tr>`).join('')}</tbody></table></div></div><div class="dashboard-columns">${allowed('team.manage')?`<form data-form="invitation" class="panel"><h3>Invite someone to serve</h3><p class="muted">They will receive an email and use their own verified account.</p>${field('email','Email address','','email','required')}${select('role_id','Role',options)}${branchSelect()}<div class="form-error" role="alert"></div><button class="button">Send invitation →</button></form><section class="panel"><h3>Invitations</h3>${state.team.invitations.length?state.team.invitations.map(i=>`<article class="invitation"><strong>${esc(i.email)}</strong><small>${i.accepted_at?'Accepted':i.revoked_at?'Revoked':i.expires_at<Date.now()?'Expired':'Awaiting acceptance'}</small>${!i.accepted_at&&!i.revoked_at?`<button class="text-button" data-revoke="${i.id}">Revoke</button>`:''}</article>`).join(''):empty('Build your team','Your invitations will appear here.')}</section>`:''}</div>`;
  }
  if(state.tab==='roles')return `${heading('THE RIGHT ACCESS','Roles & permissions.','Assign responsibility carefully. Branch scope limits where each role applies.')}<div class="dashboard-columns"><section>${state.roles.map(r=>`<article class="panel role-card"><h3>${esc(r.name)} <span class="pill">${r.builtin?'Standard':'Custom'}</span></h3><div class="permission-tags">${r.permissions.map(p=>`<span>${esc(p)}</span>`).join('')}</div>${!r.builtin&&allowed('roles.manage')&&globalScope()?roleEditor(r):''}</article>`).join('')}</section>${allowed('roles.manage')&&globalScope()?`<form data-form="role" class="panel"><h3>Create a custom role</h3>${field('name','Role name','','text','required minlength="2" maxlength="80"')}<fieldset><legend>Permissions</legend>${state.config.permissions.filter(p=>w.permissions.includes(p)).map(p=>`<label class="check"><input type="checkbox" name="permissions" value="${esc(p)}" ${p==='church.read'?'checked disabled':''}><span>${esc(p)}</span></label>`).join('')}</fieldset><small>Permissions for future ministry modules take effect when those modules are available.</small><div class="form-error" role="alert"></div><button class="button">Create role →</button></form>`:''}</div>`;
  if(state.tab==='website')return websiteEditor();
  if(state.tab==='directory')return directoryEditor();
  if(state.tab==='audit')return `${heading('ACCOUNTABILITY BUILT IN','Activity history.','A read-only record of important changes in your church workspace.')}<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Action</th><th>Person</th><th>When</th></tr></thead><tbody>${state.events.map(e=>`<tr><td><strong>${esc(pretty(e.action.replaceAll('.',' ')))}</strong><small>Record ${e.id}</small></td><td>${esc(e.actor||'System')}</td><td>${esc(new Date(e.created_at).toLocaleString(undefined,{timeZone:c.timezone}))}</td></tr>`).join('')}</tbody></table></div>${state.events.length===50?'<button class="button secondary" data-action="older-audit">Load older activity</button>':''}</section>`;
  return '';
}
function branchSelect(value=''){return select('branch_id','Access scope',[...(globalScope()?[['','Whole church']]:[]),...state.workspace.branches.map(b=>[b.id,`${b.name} and its descendants`])],value);}
function inviteScreen(){pageTitle('Join your church');root.innerHTML=`<header class="simple-header">${brand}<div class="account">${platformInboxLink()}<a href="/security">Account security</a><button class="text-button" data-action="logout">Sign out</button></div></header><main id="main" class="setup-page"><span class="eyebrow">SERVE TOGETHER</span><h1>You have been invited.</h1><p class="muted">Signed in as ${esc(state.me.user.email)}. Only the invited, verified address can accept.</p>${verificationBanner()}<form data-form="accept" class="panel"><h3>Join the church workspace</h3><p>Your church administrator has selected your role and access scope.</p><div class="form-error" role="alert"></div><button class="button" ${!state.me.user.verified?'disabled':''}>Accept invitation →</button></form></main>`;}
async function boot(){
  if(location.hash.startsWith('#token=')) {
    const token=new URLSearchParams(location.hash.slice(1)).get('token');
    sessionStorage.setItem(location.pathname==='/invite'?'invitation':location.pathname==='/reset'?'reset':'verify',token);
    history.replaceState(null,'',location.pathname+location.search);
  }
  try {
    state.config=await api('/api/config');
    if(location.pathname==='/mfa'){const challenge=await api('/api/auth/mfa/challenge');state.mfaCsrf=challenge.csrf;return mfaLogin();}
    if(['/register','/login','/forgot','/verify','/reset','/participation','/'].includes(location.pathname))return authentication();
    try{state.me=await api('/api/me');}catch(e){if(e.status===401)return authentication();throw e;}
    if(location.pathname==='/security')return await loadSecurity();
    if(location.pathname==='/platform/inbox'){const query=new URLSearchParams(location.search);return await loadInbox(query.get('status')||'new',query.get('enquiry'),Number(query.get('page')||1));}
    if(location.pathname==='/new-church')return newChurch();
    if(location.pathname==='/invite'||sessionStorage.getItem('invitation'))return inviteScreen();
    const q=new URLSearchParams(location.search),churchId=q.get('church');
    if(churchId){try{return await loadWorkspace(churchId,q.get('tab')||'overview');}catch(e){notice(e.message,true);history.replaceState(null,'','/app');}}
    workspaceChooser();
  }catch(e){root.innerHTML=`<main id="main" class="loading"><h1>We couldn’t open your workspace.</h1><p>${esc(e.message)}</p><a href="/app">Try again</a></main>`;}
}
document.addEventListener('submit',async event=>{
  const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])'),errorEl=form.querySelector('.form-error')||document.querySelector('.form-error');
  const data=Object.fromEntries(new FormData(form));if(button)button.disabled=true;if(errorEl)errorEl.textContent='';
  const base=`/api/churches/${state.churchId}`;
  try {
    let result;
    switch(form.dataset.form){
      case 'login':result=await api('/api/auth/login','POST',data);location.assign(result.mfaRequired?'/mfa':'/app');return;
      case 'mfa-login':await api('/api/auth/mfa/login','POST',data);location.assign('/app');return;
      case 'register':result=await api('/api/auth/register','POST',data);form.innerHTML=`<div class="success-mark">✓</div><h3>Check your email</h3><p>${esc(result.message)}</p><a class="button" href="/login">Continue to sign in →</a>`;return;
      case 'forgot':result=await api('/api/auth/forgot','POST',data);notice(result.message);break;
      case 'verify':result=await api('/api/auth/verify','POST',{token:sessionStorage.getItem('verify')||''});sessionStorage.removeItem('verify');form.innerHTML=`<div class="success-mark">✓</div><p>${esc(result.message)}</p><a class="button" href="/app">Continue →</a>`;return;
      case 'reset':result=await api('/api/auth/reset','POST',{...data,token:sessionStorage.getItem('reset')||''});sessionStorage.removeItem('reset');form.innerHTML=`<p>${esc(result.message)}</p><a class="button" href="/login">Sign in →</a>`;return;
      case 'church':result=await api('/api/churches','POST',{...data,acceptPolicy:data.acceptPolicy==='on',policyVersion:state.config.policyVersion});location.assign(`/app?church=${result.id}`);return;
      case 'accept':result=await api('/api/invitations/accept','POST',{token:sessionStorage.getItem('invitation')||''});sessionStorage.removeItem('invitation');location.assign(result.workspaceAccess===false?'/app':`/app?church=${result.churchId}`);return;
      case 'website-settings':case 'website-page':case 'website-entry':await saveWebsite(websiteDraftFromForms());return;
      case 'website-new-page':{const snapshot=websiteDraftFromForms();snapshot.pages.push({slug:data.slug,title:data.title,body:'',imageId:'',imageAlt:'',items:[],enabled:false,showInNav:true,allowComments:false});await saveWebsite(snapshot,data.slug);return;}
      case 'website-upload':{const file=form.elements.image.files[0];if(!file||file.size>1572864)throw Error('Choose a PNG or JPEG under 1.5 MB.');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api(`${base}/website/assets`,'POST',{name:file.name.slice(0,100),data:encoded});await loadWorkspace(state.churchId,'website');notice('Image uploaded.');return;}
      case 'directory':await api(`${base}/directory`,'PATCH',{summary:data.summary,website_url:data.website_url,published:data.published==='on',version:Number(form.dataset.version)});break;
      case 'enquiry-status':await api(`/api/platform/enquiries/${form.dataset.id}`,'PATCH',{status:data.status,version:Number(form.dataset.version)});await loadInbox(state.inboxStatus,form.dataset.id,state.inboxPage);notice('Status updated.');return;
      case 'enquiry-reply':await api(`/api/platform/enquiries/${form.dataset.id}/replies`,'POST',{message:data.message,resolve:data.resolve==='on',version:Number(form.dataset.version)});await loadInbox(state.inboxStatus,form.dataset.id,state.inboxPage);notice('Reply saved and queued for email delivery.');return;
      case 'profile':await api(base,'PATCH',data);break;
      case 'statement':await api(`${base}/statements`,'POST',data);break;
      case 'statement-edit':await api(`${base}/statements/${form.dataset.id}`,'PATCH',{...data,position:Number(data.position)});break;
      case 'branch':await api(`${base}/branches`,'POST',data);break;
      case 'invitation':await api(`${base}/invitations`,'POST',data);break;
      case 'member':await api(`${base}/team/${form.dataset.id}`,'PATCH',data);break;
      case 'role-edit':await api(`${base}/roles/${form.dataset.id}`,'PATCH',{name:data.name,version:form.dataset.version,permissions:['church.read',...new FormData(form).getAll('permissions')],confirmExpansion:data.confirmExpansion==='on'});break;
      case 'mfa-setup':state.mfaSetup=await api('/api/auth/mfa/setup','POST',data);state.recoveryCodes=[];await loadSecurity();return;
      case 'mfa-confirm':result=await api('/api/auth/mfa/confirm','POST',data);state.mfaSetup=null;state.recoveryCodes=result.codes;state.me=await api('/api/me');await loadSecurity();notice('Two-step verification enabled. Save your recovery codes.');return;
      case 'mfa-manage':result=await api(data.action==='disable'?'/api/auth/mfa/disable':'/api/auth/mfa/recovery-codes','POST',data);state.mfaSetup=null;state.recoveryCodes=result.codes||[];state.me=await api('/api/me');await loadSecurity();notice(result.message);return;
      case 'password-change':{
        if(data.password!==data.confirmPassword)throw new Error('The new passwords do not match.');
        result=await api('/api/auth/password','POST',{currentPassword:data.currentPassword,password:data.password});
        state.me=await api('/api/me');await loadSecurity();notice(result.message);return;
      }
      case 'role':await api(`${base}/roles`,'POST',{name:data.name,permissions:['church.read',...new FormData(form).getAll('permissions')]});break;
    }
    if(!['forgot'].includes(form.dataset.form)){await loadWorkspace(state.churchId,state.tab);notice(form.dataset.form==='invitation'?'Invitation queued for delivery.':'Saved successfully.');}
  }catch(e){if(errorEl)errorEl.textContent=e.message;else notice(e.message,true);}finally{if(button)button.disabled=false;}
});
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-tab],[data-church],[data-action],[data-revoke],[data-remove-member],[data-delete-statement],[data-archive-role],[data-revoke-session],[data-enquiry],[data-inbox-filter],[data-inbox-page],[data-site-section],[data-site-page],[data-site-entry],[data-site-action],[data-site-restore],[data-site-delete-image],[data-site-review],[data-site-message-status],[data-site-move-page],[data-site-move-entry]');if(!el)return;
  try{
    if(el.dataset.siteSection||el.dataset.sitePage||el.dataset.siteEntry!==undefined){if(state.websiteDirty&&!confirm('Leave unsaved website changes?'))return;state.websiteDirty=false;if(el.dataset.siteSection)state.websiteSection=el.dataset.siteSection;if(el.dataset.sitePage){state.websitePage=el.dataset.sitePage;state.websiteEntry='';}if(el.dataset.siteEntry!==undefined)state.websiteEntry=el.dataset.siteEntry;renderWorkspace();return;}
    if(el.dataset.siteMovePage||el.dataset.siteMoveEntry){const snapshot=websiteDraftFromForms(),list=el.dataset.siteMovePage?snapshot.pages:snapshot.pages.find(p=>p.slug===state.websitePage).items,index=list.findIndex(p=>p.slug===(el.dataset.siteMovePage||el.dataset.siteMoveEntry)),next=index+Number(el.dataset.direction);if(index>=0&&next>=0&&next<list.length){[list[index],list[next]]=[list[next],list[index]];await saveWebsite(snapshot);}return;}
    if(el.dataset.siteMessageStatus){state.websiteMessageStatus=el.dataset.siteMessageStatus;await loadWorkspace(state.churchId,'website');return;}
    if(el.dataset.siteAction){const base=`/api/churches/${state.churchId}/website`;if(state.websiteDirty)throw Error('Save your changes first.');if(el.dataset.siteAction==='older-revisions'){const rows=await api(base+'/revisions?before='+state.websiteRevisions.at(-1).version);state.websiteRevisions.push(...rows.revisions);state.websiteRevisionsMore=rows.revisions.length===30;renderWorkspace();return;}if(el.dataset.siteAction==='older-messages'){const rows=await api(base+'/messages?status='+state.websiteMessageStatus+'&before='+state.websiteMessages.at(-1).cursor);state.websiteMessages.push(...rows.messages);state.websiteMessagesMore=rows.messages.length===25;renderWorkspace();return;}if(el.dataset.siteAction==='import-purpose'){await api(base+'/import-purpose','POST',{version:state.website.version});await loadWorkspace(state.churchId,'website');notice('Visions and missions copied to the website draft.');return;}if(el.dataset.siteAction==='publish'){await api(base+'/publish','POST',{version:state.website.version});notice('Website published.');}else if(el.dataset.siteAction==='unpublish'){if(!confirm('Take this church website offline?'))return;await api(base+'/publish','DELETE',{version:state.website.publication.version});notice('Website taken offline.');}else if(el.dataset.siteAction==='remove-entry'){const snapshot=websiteDraftFromForms();snapshot.pages.find(p=>p.slug===state.websitePage).items=snapshot.pages.find(p=>p.slug===state.websitePage).items.filter(i=>i.slug!==state.websiteEntry);state.websiteEntry='';await saveWebsite(snapshot);return;}await loadWorkspace(state.churchId,'website');return;}
    if(el.dataset.siteRestore){if(!confirm('Restore this revision as a new draft? The live website will stay unchanged.'))return;await api(`/api/churches/${state.churchId}/website/restore`,'POST',{revision:Number(el.dataset.siteRestore),version:state.website.version});await loadWorkspace(state.churchId,'website');notice('Revision restored as a new draft.');return;}
    if(el.dataset.siteDeleteImage){if(!confirm('Delete this unused image? Older revisions may need a replacement.'))return;await api(`/api/churches/${state.churchId}/website/assets/${el.dataset.siteDeleteImage}`,'DELETE',{});await loadWorkspace(state.churchId,'website');notice('Image deleted.');return;}
    if(el.dataset.siteReview){await api(`/api/churches/${state.churchId}/website/messages/${el.dataset.id}`,'PATCH',{status:el.dataset.siteReview,version:Number(el.dataset.version)});await loadWorkspace(state.churchId,'website');notice('Message reviewed.');return;}
    if(el.dataset.enquiry)return await loadInbox(state.inboxStatus,el.dataset.enquiry,state.inboxPage);
    if(el.dataset.inboxFilter)return await loadInbox(el.dataset.inboxFilter);
    if(el.dataset.inboxPage)return await loadInbox(state.inboxStatus,null,Number(el.dataset.inboxPage));
    if((el.dataset.tab||el.dataset.church)&&state.websiteDirty&&!confirm('Leave unsaved website changes?'))return;
    if(el.dataset.tab)return await loadWorkspace(state.churchId,el.dataset.tab);
    if(el.dataset.church)return await loadWorkspace(el.dataset.church);
    if(el.dataset.action==='logout'){await api('/api/auth/logout','POST',{});location.assign('/login');return;}
    if(el.dataset.action==='logout-others'){const r=await api('/api/auth/logout-others','POST',{});await loadSecurity();return notice(r.message);}
    if(el.dataset.revokeSession){const r=await api(`/api/auth/sessions/${el.dataset.revokeSession}`,'DELETE',{});if(r.signedOut){location.assign('/login');return;}await loadSecurity();return notice(r.message);}
    if(el.dataset.archiveRole){
      const role=state.roles.find(r=>r.id===el.dataset.archiveRole);
      if(!confirm(`Archive the custom role “${role.name}”? Members must be reassigned and pending invitations revoked first.`))return;
      const r=await api(`/api/churches/${state.churchId}/roles/${role.id}`,'DELETE',{version:role.version});
      await loadWorkspace(state.churchId,'roles');return notice(r.message);
    }
    if(el.dataset.action==='resend'){const r=await api('/api/auth/resend','POST',{});return notice(r.message);}
    if(el.dataset.action==='older-audit'){const events=(await api(`/api/churches/${state.churchId}/audit?before=${state.events.at(-1).id}`)).events;state.events=events;renderWorkspace();return;}
    const action=el.dataset.revoke?'revoke this invitation':el.dataset.removeMember?'suspend this worker dashboard and keep their church membership':'delete this statement';
    if(!confirm(`Do you want to ${action}?`))return;
    const path=el.dataset.revoke?`invitations/${el.dataset.revoke}`:el.dataset.removeMember?`team/${el.dataset.removeMember}`:`statements/${el.dataset.deleteStatement}`;
    await api(`/api/churches/${state.churchId}/${path}`,'DELETE',{});await loadWorkspace(state.churchId,state.tab);notice('Updated successfully.');
  }catch(e){notice(e.message,true);}
});

function roleEditor(role){
  const permitted=state.config.permissions.filter(p=>state.workspace.permissions.includes(p));
  return `<details><summary>Edit custom role</summary><form data-form="role-edit" data-id="${esc(role.id)}" data-version="${esc(role.version)}">${field('name','Role name',role.name,'text','required minlength="2" maxlength="80"')}<p class="muted">${role.assigned_members} member(s) and ${role.pending_invitations} pending invitation(s) use this role. Changes take effect immediately.</p><fieldset><legend>Permissions</legend>${permitted.map(p=>`<label class="check"><input type="checkbox" name="permissions" value="${esc(p)}" ${role.permissions.includes(p)?'checked':''} ${p==='church.read'?'disabled':''}><span>${esc(p)}</span></label>`).join('')}</fieldset><label class="check"><input type="checkbox" name="confirmExpansion"><span>I have reviewed any added permissions and authorise the additional access for existing members and invitees.</span></label><div class="form-error" role="alert"></div><button class="button secondary">Save role changes</button></form></details><button class="text-button danger" data-archive-role="${esc(role.id)}">Archive unused role</button>`;
}
async function loadSecurity(){
  const [sessions,mfa]=await Promise.all([api('/api/auth/sessions'),api('/api/auth/mfa')]);state.sessions=sessions.sessions;state.mfa=mfa;if(mfa.enabled)state.mfaSetup=null;
  pageTitle('Account security');
  root.innerHTML=`<header class="simple-header">${brand}<div class="account"><a href="/app">Your churches</a><button class="text-button" data-action="logout">Sign out</button></div></header><main id="main" class="security-page">${heading('YOUR PERSONAL ACCOUNT','Keep your account secure.','These settings apply to your account across all your church workspaces.')}<div class="dashboard-columns"><form data-form="password-change" class="panel"><h3>Change your password</h3><p class="muted">Changing your password signs out other sessions and invalidates outstanding password-reset links.</p>${field('currentPassword','Current password','','password','required maxlength="256" autocomplete="current-password"')}${field('password','New password','','password','required minlength="12" maxlength="256" autocomplete="new-password"')}${field('confirmPassword','Confirm new password','','password','required minlength="12" maxlength="256" autocomplete="new-password"')}<small>Use a unique passphrase with at least 12 characters.</small><div class="form-error" role="alert"></div><button class="button">Change password →</button></form><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SIGNED IN AS</span><h3>${esc(state.me.user.email)}</h3></div></div><h3>Active sessions</h3><p class="muted">Each sign-in lasts up to 12 hours. Sign out any session you no longer use.</p>${state.sessions.map(session=>`<article class="session-row"><div><strong>${session.current?'This session':'Another session'}</strong>${session.current?'<span class="pill">Current</span>':''}<small>Signed in ${esc(new Date(session.startedAt).toLocaleString())}</small><small>Expires ${esc(new Date(session.expiresAt).toLocaleString())}</small></div><button class="text-button" data-revoke-session="${esc(session.id)}">Sign out${session.current?' here':''}</button></article>`).join('')}${state.sessions.length>1?'<button class="button secondary" data-action="logout-others">Sign out all other sessions</button>':''}</section></div>${mfaPanel()}<footer>${credit}</footer></main>`;
}


function mfaLogin(){
  authFrame('One more security check','Enter an authenticator code or one of your unused recovery codes.',`<form data-form="mfa-login">${field('code','Authenticator or recovery code','','text','required maxlength="100" autocomplete="one-time-code" autocapitalize="off" spellcheck="false"')}<button class="button">Complete sign-in →</button></form><p class="auth-link"><a href="/login">Start sign-in again</a></p>`);
}
function mfaPanel(){
  const status=state.mfa;
  const recovery=state.recoveryCodes.length?`<section class="panel recovery-panel" aria-label="New recovery codes"><h3>Save these recovery codes now</h3><p>Each code works once if you lose access to your authenticator. Store them privately, away from your password. They will disappear when you leave or reload this page.</p><div class="recovery-grid">${state.recoveryCodes.map(code=>`<code>${esc(code)}</code>`).join('')}</div></section>`:'';
  if(status.enabled)return `${recovery}<section class="panel"><div class="panel-heading"><div><span class="eyebrow">AN EXTRA LAYER OF PROTECTION</span><h3>Two-step verification</h3></div><span class="pill">Enabled</span></div><p>Your account uses authenticator codes. ${status.recoveryCodesRemaining} recovery codes remain.</p><details><summary>Replace recovery codes or turn off verification</summary><form data-form="mfa-manage" class="wide-form">${field('currentPassword','Current password','','password','required maxlength="256" autocomplete="current-password"')}${field('code','Fresh authenticator or unused recovery code','','text','required maxlength="100" autocomplete="one-time-code" autocapitalize="off" spellcheck="false"')}${select('action','Action',[['replace','Replace all recovery codes'],['disable','Turn off two-step verification']])}<p class="muted">Replacing codes invalidates all previous recovery codes. Turning off verification removes the extra sign-in check. Either action signs out other sessions.</p><div class="form-error" role="alert"></div><button class="button secondary">Apply security change</button></form></details></section>`;
  if(state.mfaSetup)return `<section class="panel"><span class="eyebrow">FINISH SETUP WITHIN TEN MINUTES</span><h3>Add JesusSeat to your authenticator</h3><p>In your authenticator app, choose to enter a setup key manually. Select a time-based code (30 seconds), use the account ${esc(state.mfaSetup.account)}, and enter this key:</p><code class="setup-key">${esc(state.mfaSetup.secret)}</code><p>Keep this key private. JesusSeat does not send it to an external QR service.</p><form data-form="mfa-confirm" class="wide-form">${field('code','Current six-digit authenticator code','','text','required pattern="[0-9]{6}" inputmode="numeric" autocomplete="one-time-code" maxlength="6"')}<div class="form-error" role="alert"></div><button class="button">Confirm and enable →</button></form></section>`;
  return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">PROTECT YOUR MINISTRY ACCESS</span><h3>Two-step verification</h3></div><span class="pill">Not enabled</span></div><p>Use an authenticator app to add a six-digit code to sign-in. You will also receive ten recovery codes.</p><form data-form="mfa-setup" class="wide-form">${field('currentPassword','Confirm your current password','','password','required maxlength="256" autocomplete="current-password"')}<div class="form-error" role="alert"></div><button class="button secondary">Set up authenticator →</button></form></section>`;
}


function platformInboxLink(){return state.me?.platformAdmin?'<a href="/platform/inbox">Platform inbox</a>':'';}
function directoryEditor(){
 const listing=state.directory,c=state.workspace.church;
 return `${heading('A PUBLIC INTRODUCTION','Share your church. On your terms.','Choose whether your church appears in the JesusSeat directory.')}<div class="dashboard-columns"><form class="panel" data-form="directory" data-version="${listing.version}"><h3>Your public listing</h3><p class="muted">Publishing shares ${esc(c.name)}, ${esc(c.city)}, ${esc(c.country)}, the introduction below and your optional website link. It does not publish private contact details or member records.</p>${area('summary','Public introduction',listing.summary,'maxlength="1500" placeholder="A short welcome to your church community…"')}${field('website_url','Existing website (optional)',listing.website_url,'url','maxlength="1000" placeholder="https://your-church.example"')}<label class="check"><input type="checkbox" name="published" ${listing.published?'checked':''}><span>I am authorised to publish this church introduction in the public directory.</span></label><div class="form-error" role="alert"></div><button class="button">Save public listing →</button></form><aside class="panel purpose-aside"><span class="eyebrow">YOU CHOOSE WHAT TO SHARE</span><h3>${listing.published?'Your church is listed.':'Your listing is private.'}</h3><p>Turn off publication to remove the listing. A directory entry is not a platform verification badge.</p>${listing.published?`<a class="button secondary" href="/churches/${esc(c.slug)}" target="_blank" rel="noopener">View public introduction ↗</a>`:'<a class="button secondary" href="/churches" target="_blank" rel="noopener">Explore the directory ↗</a>'}</aside></div>`;
}
async function loadInbox(status='new',selected=null,page=1){
 state.inboxStatus=status;state.inboxPage=page;state.inbox=await api(`/api/platform/enquiries?status=${encodeURIComponent(status)}&page=${page}`);
 state.enquiry=selected?await api(`/api/platform/enquiries/${encodeURIComponent(selected)}`):null;
 history.replaceState(null,'',`/platform/inbox?status=${encodeURIComponent(status)}&page=${page}${selected?'&enquiry='+encodeURIComponent(selected):''}`);
 pageTitle('Platform enquiries');
 const counts=Object.fromEntries(state.inbox.counts.map(c=>[c.status,c.total])),item=state.enquiry?.enquiry;
 root.innerHTML=`<header class="simple-header">${brand}<div class="account"><a href="/">Public website</a><a href="/app">Your churches</a><a href="/security">Account security</a><button class="text-button" data-action="logout">Sign out</button></div></header><main id="main" class="platform-page">${heading('JESUSSEAT PLATFORM','Every message deserves a hearing.','Public contact enquiries, private to authorised platform administrators.')}<nav class="inbox-filters" aria-label="Filter enquiries">${['new','open','resolved','all'].map(key=>`<button class="button ${status===key?'':'secondary'}" data-inbox-filter="${key}">${pretty(key)} ${key==='all'?Object.values(counts).reduce((a,b)=>a+b,0):counts[key]||0}</button>`).join('')}</nav><div class="inbox-layout"><section class="panel inbox-list"><h3>Enquiries</h3>${state.inbox.enquiries.length?state.inbox.enquiries.map(e=>`<button class="enquiry-list-item ${item?.id===e.id?'selected':''}" data-enquiry="${e.id}"><span class="eyebrow">${esc(e.topic)} · ${esc(e.status)}</span><strong>${esc(e.subject)}</strong><span>${esc(e.name)}</span><small>${esc(new Date(e.created_at).toLocaleString())}</small></button>`).join(''):empty('No enquiries here','New contact messages will appear after they are submitted.')}<div class="inbox-pagination">${page>1?`<button class="text-button" data-inbox-page="${page-1}">← Previous</button>`:''}${state.inbox.enquiries.length===25?`<button class="text-button" data-inbox-page="${page+1}">Next →</button>`:''}</div></section><section>${item?`<article class="panel"><span class="eyebrow">REFERENCE ${esc(item.id.slice(0,8).toUpperCase())} · ${esc(item.topic)}</span><h2 class="enquiry-title">${esc(item.subject)}</h2><p class="muted">${esc(item.name)} · ${esc(item.email)}</p><p class="preserve">${esc(item.message)}</p><small>Received ${esc(new Date(item.created_at).toLocaleString())} · Privacy notice ${esc(item.privacy_version)}</small><form class="enquiry-status-form" data-form="enquiry-status" data-id="${item.id}" data-version="${item.version}">${select('status','Status',[['new','New'],['open','Open'],['resolved','Resolved']],item.status)}<div class="form-error" role="alert"></div><button class="button secondary">Save status</button></form></article>${state.enquiry.replies.map(reply=>`<article class="panel reply-card"><span class="eyebrow">PLATFORM REPLY · ${esc(reply.author)}</span><p class="preserve">${esc(reply.message)}</p><small>${esc(new Date(reply.created_at).toLocaleString())} · Email queued</small></article>`).join('')}<form class="panel" data-form="enquiry-reply" data-id="${item.id}" data-version="${item.version}"><h3>Reply to ${esc(item.name)}</h3>${area('message','Your reply','','required minlength="5" maxlength="5000"')}<label class="check"><input type="checkbox" name="resolve"><span>Mark resolved after this reply.</span></label><p class="muted">The reply is saved and queued for delivery to ${esc(item.email)}. Delivery requires the configured email provider.</p><div class="form-error" role="alert"></div><button class="button">Queue reply →</button></form>`:empty('Choose a conversation','Open an enquiry to read the message, reply or update its status.')}</section></div></main>`;
}

boot();

function websiteImageSelect(name,label,value=''){return select(name,label,[['','No image'],...state.websiteAssets.map(a=>[a.id,a.name])],value);}
function websiteEditor(){
 const w=state.website,s=w.snapshot.settings,p=w.snapshot.pages.find(p=>p.slug===state.websitePage)||w.snapshot.pages[0],section=state.websiteSection;
 const tabs=[['pages','Pages'],['settings','Design & details'],['images','Images'],['history','Revisions'],['messages','Enquiries & comments']];
 let body='';
 if(section==='settings')body=`<form class="panel" data-form="website-settings"><h3>Your church, beautifully presented.</h3><div class="site-designs">${state.config.templates.map(t=>`<label><input type="radio" name="template" value="${t}" ${s.template===t?'checked':''}><img src="/assets/${t}.webp" alt="${esc(pretty(t))} design preview" loading="lazy"><strong>${esc(pretty(t))}</strong></label>`).join('')}</div>${field('name','Public church name',s.name,'text','required maxlength="160"')}${field('tagline','Tagline',s.tagline,'text','maxlength="180"')}${field('heroTitle','Welcome heading',s.heroTitle,'text','required maxlength="200"')}${area('heroText','Welcome message',s.heroText,'maxlength="3000"')}${websiteImageSelect('logoId','Church logo',s.logoId)}${websiteImageSelect('heroId','Welcome image',s.heroId)}${field('heroAlt','Welcome image description',s.heroAlt,'text','maxlength="250"')}<div class="form-grid">${field('email','Public contact email',s.email,'email')}${field('phone','Public phone',s.phone,'tel','maxlength="50"')}</div>${area('address','Public address',s.address,'maxlength="500"')}${area('serviceTimes','Service times',s.serviceTimes,'maxlength="1500"')}<div class="form-error" role="alert"></div><button class="button">Save design & details →</button></form>`;
 if(section==='pages'){
  const entry=p.items.find(i=>i.slug===state.websiteEntry)||{slug:'',title:'',body:'',date:'',imageId:'',imageAlt:'',url:'',linkLabel:''};
  body=`<div class="site-editor-grid"><aside class="panel site-page-list"><h3>Website pages</h3><button class="text-button" data-site-action="import-purpose">Copy visions & missions ↗</button>${w.snapshot.pages.map(page=>`<div class="site-sort-row"><button class="text-button ${page.slug===p.slug?'selected':''}" data-site-page="${page.slug}">${esc(page.title)} <small>${page.enabled?'Visible':'Hidden'}</small></button><button class="text-button" data-site-move-page="${page.slug}" data-direction="-1" aria-label="Move ${esc(page.title)} up">↑</button><button class="text-button" data-site-move-page="${page.slug}" data-direction="1" aria-label="Move ${esc(page.title)} down">↓</button></div>`).join('')}<details><summary>Add a page</summary><form data-form="website-new-page">${field('title','Page title','','text','required maxlength="160"')}${field('slug','Page address','','text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="60"')}<div class="form-error" role="alert"></div><button class="button secondary">Create page</button></form></details></aside><div><form class="panel" data-form="website-page"><span class="eyebrow">/${p.slug==='home'?'':esc(p.slug)}</span><h3>${esc(p.title)}</h3>${field('title','Page title',p.title,'text','required maxlength="160"')}${area('body','Page text',p.body,'maxlength="12000"')}${websiteImageSelect('imageId','Page image',p.imageId)}${field('imageAlt','Image description',p.imageAlt,'text','maxlength="250"')}<label class="check"><input type="checkbox" name="enabled" ${p.enabled?'checked':''} ${p.slug==='home'?'disabled':''}><span>Show this page</span></label><label class="check"><input type="checkbox" name="showInNav" ${p.showInNav?'checked':''}><span>Include in navigation</span></label><label class="check"><input type="checkbox" name="allowComments" ${p.allowComments?'checked':''}><span>Allow comments, with approval before publication</span></label><div class="form-error" role="alert"></div><button class="button">Save page →</button></form><section class="panel"><h3>Page entries</h3><p class="muted">Visions, missions, people, events, gallery photos and other entries each have their own page.</p><div class="site-entry-list">${p.items.map(i=>`<div class="site-sort-row"><button class="text-button" data-site-entry="${esc(i.slug)}">${esc(i.title)} ↗</button><button class="text-button" data-site-move-entry="${i.slug}" data-direction="-1" aria-label="Move ${esc(i.title)} up">↑</button><button class="text-button" data-site-move-entry="${i.slug}" data-direction="1" aria-label="Move ${esc(i.title)} down">↓</button></div>`).join('')}<button class="button secondary" data-site-entry="">Add entry</button></div></section><form class="panel" data-form="website-entry"><h3>${state.websiteEntry?'Edit entry':'Add an entry'}</h3>${field('slug','Entry address',entry.slug,'text',`required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="60" ${state.websiteEntry?'readonly':''}`)}${field('title','Entry title',entry.title,'text','required maxlength="160"')}${area('body','Entry text',entry.body,'maxlength="8000"')}${field('date','Date (optional)',entry.date,'date')}${websiteImageSelect('imageId','Entry image',entry.imageId)}${field('imageAlt','Image description',entry.imageAlt,'text','maxlength="250"')}${field('url','External link (optional)',entry.url,'url','maxlength="1000" placeholder="https://"')}${field('linkLabel','Link label',entry.linkLabel,'text','maxlength="100"')}<div class="form-error" role="alert"></div><button class="button">Save entry →</button>${state.websiteEntry?'<button type="button" class="text-button danger" data-site-action="remove-entry">Remove entry</button>':''}</form></div></div>`;
 }
 if(section==='images')body=`<section class="panel"><h3>Church images</h3><p class="muted">PNG or JPEG, up to 1.5 MB per image. Website allowance: 100 images / 25 MB. Upload only images you have permission to publish.</p><form data-form="website-upload"><label>Choose an image<input name="image" type="file" accept="image/png,image/jpeg" required></label><div class="form-error" role="alert"></div><button class="button">Upload image →</button></form></section><div class="site-image-library">${state.websiteAssets.map(a=>`<article class="panel"><img src="/website-preview/${state.churchId}/media/${a.id}" alt="${esc(a.name)}" loading="lazy"><strong>${esc(a.name)}</strong><small>${a.width} × ${a.height} · ${Math.ceil(a.size/1024)} KB</small><button class="text-button danger" data-site-delete-image="${a.id}">Delete unused image</button></article>`).join('')}</div>`;
 if(section==='history')body=`<section class="panel"><h3>Saved revisions</h3>${state.websiteRevisions.length?state.websiteRevisions.map(r=>`<article class="site-revision"><div><strong>Revision ${r.version}</strong><small>${esc(new Date(r.created_at).toLocaleString())}</small></div><a class="text-button" href="/website-preview/${state.churchId}?revision=${r.version}" target="_blank" rel="noopener">Preview ↗</a><button class="button secondary" data-site-restore="${r.version}">Restore as draft</button></article>`).join(''):'<p>No saved revisions yet.</p>'}${state.websiteRevisionsMore?`<button class="text-button" data-site-action="older-revisions">Older revisions →</button>`:''}</section>`;
 if(section==='messages')body=`<section class="panel"><h3>Church messages</h3><nav class="inbox-filters" aria-label="Website message status">${['pending','approved','rejected','resolved'].map(status=>`<button class="button ${state.websiteMessageStatus===status?'':'secondary'}" data-site-message-status="${status}">${pretty(status)}</button>`).join('')}</nav>${state.websiteMessages.length?state.websiteMessages.map(m=>`<article class="site-message"><span class="eyebrow">${esc(m.kind)} · ${esc(m.page_slug)}</span><h3>${esc(m.name)}</h3><p class="muted">${esc(m.email)} · ${esc(new Date(m.created_at).toLocaleString())}</p><p class="preserve">${esc(m.message)}</p>${(m.kind==='comment'?(m.status==='pending'?[['approved','Approve for publication'],['rejected','Reject']]:m.status==='approved'?[['pending','Return to review'],['rejected','Remove from website']]:[['pending','Return to review']]):m.status==='pending'?[['resolved','Mark resolved']]:[['pending','Reopen']]).map(([status,label])=>`<button class="button secondary" data-site-review="${status}" data-id="${m.id}" data-version="${m.version}">${label}</button>`).join(' ')}</article>`).join(''):'<p>No messages here.</p>'}${state.websiteMessagesMore?'<button class="text-button" data-site-action="older-messages">Older messages →</button>':''}</section>`;
 return `${heading('YOUR CHURCH ONLINE','A home for your church.','Make it yours. Preview it. Share it.')}<section class="panel site-publishing"><div><strong>Draft ${w.version||'not saved'}</strong><small>${w.publication?'Live revision '+w.publication.version:'Website offline'}</small><a href="/c/${w.slug}" target="_blank" rel="noopener">/c/${esc(w.slug)} ↗</a></div><div><a class="button secondary" href="/website-preview/${state.churchId}" target="_blank" rel="noopener">Preview saved draft ↗</a>${w.canPublish?`<button class="button" data-site-action="publish">Publish website →</button>${w.publication?'<button class="text-button danger" data-site-action="unpublish">Take offline</button>':''}`:'<span class="muted">A website publisher can make your draft live.</span>'}</div></section><nav class="inbox-filters" aria-label="Website editor">${tabs.map(([key,label])=>`<button class="button ${key===section?'':'secondary'}" data-site-section="${key}">${label}</button>`).join('')}</nav>${body}`;
}
function websiteDraftFromForms(){
 const snapshot=JSON.parse(JSON.stringify(state.website.snapshot)),settings=document.querySelector('[data-form="website-settings"]'),pageForm=document.querySelector('[data-form="website-page"]'),entryForm=document.querySelector('[data-form="website-entry"]');
 if(settings)Object.assign(snapshot.settings,Object.fromEntries(new FormData(settings)));
 const p=snapshot.pages.find(p=>p.slug===state.websitePage);
 if(pageForm){const data=Object.fromEntries(new FormData(pageForm));Object.assign(p,data,{enabled:p.slug==='home'||data.enabled==='on',showInNav:data.showInNav==='on',allowComments:data.allowComments==='on'});}
 if(entryForm){const data=Object.fromEntries(new FormData(entryForm));if(data.title){const index=p.items.findIndex(i=>i.slug===state.websiteEntry);if(index>=0)p.items[index]=data;else p.items.push(data);}}
 return snapshot;
}
async function saveWebsite(snapshot,nextPage){await api(`/api/churches/${state.churchId}/website`,'PATCH',{version:state.website.version,snapshot});if(nextPage)state.websitePage=nextPage;state.websiteEntry='';await loadWorkspace(state.churchId,'website');notice('Website draft saved.');}
document.addEventListener('input',event=>{if(event.target.closest('form[data-form^="website-"]'))state.websiteDirty=true;});

window.addEventListener('beforeunload',event=>{if(state.websiteDirty){event.preventDefault();event.returnValue='';}});
